<?php

namespace App\Http\Controllers;

use App\Models\Event;
use App\Models\CustomField;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;

class EventController extends Controller
{
    public function __construct()
    {
        $this->middleware('auth');
    }

    public function index()
    {
        $events = Event::all();
        return view('events.index', compact('events'));
    }

    public function create()
    {
        return view('events.create');
    }

    public function store(Request $request)
    {
        $validatedData = $request->validate([
            'eventName' => 'required',
            'image' => 'required|image|mimes:jpeg,png,jpg,gif,svg|max:2048',
            'price' => 'required|numeric',
            'location' => 'required',
            'desc' => 'required',
        ]);

        $image = $request->file('image');
        $imageName = Auth::id() . '-' . time() . '.' . $image->getClientOriginalExtension();
        $image->move(public_path('images'), $imageName);

        $event = Event::create([
            'user_id' => Auth::id(),
            'eventName' => $validatedData['eventName'],
            'image' => $imageName,
            'price' => $validatedData['price'],
            'location' => $validatedData['location'],
            'desc' => $validatedData['desc'],
        ]);

        if ($request->has('customFields')) {
            $customFields = $request->input('customFields');
            foreach ($customFields as $customField) {
                CustomField::create([
                    'event_id' => $event->id,
                    'customInputName' => $customField['customInputName'],
                    'inputType' => $customField['inputType'],
                    'validation' => implode(',', $customField['validation']),
                ]);
            }
        }

        return redirect()->route('events.index')->with('success', 'Event created successfully.');
    }

    public function edit(Event $event)
    {
        return view('events.edit', compact('event'));
    }

    public function update(Request $request, Event $event)
    {
        $validatedData = $request->validate([
            'eventName' => 'required',
            'image' => 'nullable|image|mimes:jpeg,png,jpg,gif,svg|max:2048',
            'price' => 'required|numeric',
            'location' => 'required',
            'desc' => 'required',
        ]);

        $image = $request->file('image');
        if ($image) {
            $imageName = Auth::id() . '-' . time() . '.' . $image->getClientOriginalExtension();
            $image->move(public_path('images'), $imageName);
            $event->update([
                'image' => $imageName,
            ]);
        }

        $event->update([
            'eventName' => $validatedData['eventName'],
            'price' => $validatedData['price'],
            'location' => $validatedData['location'],
            'desc' => $validatedData['desc'],
        ]);

        if ($request->has('customFields')) {
            $customFields = $request->input('customFields');
            foreach ($customFields as $customField) {
                $customField = CustomField::find($customField['id']);
                $customField->update([
                    'customInputName' => $customField['customInputName'],
                    'inputType' => $customField['inputType'],
                    'validation' => implode(',', $customField['validation']),
                ]);
            }
        }

        return redirect()->route('events.index')->with('success', 'Event updated successfully.');
    }

    public function destroy(Event $event)
    {
        $event->delete();
        return redirect()->route('events.index')->with('success', 'Event deleted successfully.');
    }
}


