        int sign = 1;

        for (size_t dimension = 0; dimension &lt; N; dimension++) {
            determinant += sign * matrix[0][dimension] * getDeterminant(subMatrix(matrix, 0, dimension));
            sign = -sign;
        }
    }

    else {
        throw std::invalid_argument(&quot;expected square matrix&quot;);
    }

