                        {'geometry': [[0.2060546875, 0.1923828125], [0.730712890625, 0.23046875]]}
                    ]
                }
            ]
        }
    ]
}
"""

tree_dict = yaml.load(tree_str, Loader=yaml.Loader)

# Calculate the sum and average of all values in the dict by key name
sum_dict = {key: sum(value) for key, value in tree_dict.items() if isinstance(value, (int, float))}
average_dict = {key: sum_dict[key] / len(value) for key, value in tree_dict.items() if isinstance(value, (list, tuple))}

