#     count = 0
#     i = j = k = 0
#     while i < len(indices1) and j < len(indices2) and k < len(indices3):
#         if indices1[i] < indices2[j] and indices2[j] < indices3[k]:
#             count += 1
#             i += 1
#         elif indices2[j] < indices3[k]:
#             j += 1
#         else:
#             k += 1
#     return count

# O(n log n)
# def count_pairs(s1, s2, s3):
#     # Create a list of indices for each string
#     indices1 = list(range(len(s1)))
#     indices2 = list(range(len(s2)))
#     indices3 = list(range(len(s3)))
#     
#     # Sort the indices using merge sort
#     def merge_sort(arr):
#         if len(arr) <= 1:
#             return arr
#         mid = len(arr) // 2

Certainly! Your current approach involves calculating the Euclidean distance for each point and then sorting them, which can be computationally expensive. An efficient way to achieve this would be to use a priority queue (min heap) to keep track of the closest points. This way, you can dynamically update the closest points without needing to sort the entire list each time.

Here's how you can implement this in JavaScript:

```javascript
class PriorityQueue {
    constructor() {
        this.heap = [];
    }

    swap(i, j) {
        [this.heap[i], this.heap[j]] = [this.heap[j], this.heap[i]];
    }

    push(item) {
        this.heap.push(item);
        let index = this.heap.length - 1;
        while (index > 0) {
            let parentIndex = Math.floor((index - 1) / 2);
            if (this.heap[parentIndex].distance > this.heap[index].distance) {
                this.swap(index, parentIndex);
                index = parentIndex;
            } else {
                break;
            }
        }
    }

    pop() {
        if (!this.heap.length) return null;
        if (this.heap.length === 1) return this.heap.pop();
        let min = this.heap[0];
        this.heap[0] = this.heap.pop();
        let index = 0;
        while (true) {
            let leftChildIndex = 2 * index + 1;
            let rightChildIndex = 2 * index + 2;
            let leftChild = this.heap[leftChildIndex];
            let rightChild = this.heap[rightChildIndex];
            let swapIndex;
            if (leftChildIndex < this.heap.length && this.heap[leftChildIndex].distance < this.heap[index].distance) {
                swapIndex = leftChildIndex;
            }
            if (rightChildIndex < this.heap.length && (swapIndex === undefined || this.heap[rightChildIndex].distance < this.heap[swapIndex].distance)) {
                swapIndex = rightChildIndex;
            }
            if (swapIndex === undefined) break;
            this.swap(index, swapIndex);
            index = swapIndex;
        }
        return min;
    }
}

function closestPoints(points, pointOfInterest, k) {
    const pq = new PriorityQueue();
    points.forEach(([x, y]) => {
        const distance = Math.sqrt((x - pointOfInterest[0]) ** 2 + (y - pointOfInterest[1]) ** 2);
        pq.push({ distance, point: [x, y] });
    });

    const result = [];
    for (let i = 0; i < k; i++) {
        result.push(pq.pop().point);
    }

    return result;
}

// Example usage
const pointOfInterest = [103, 1.3];
const data = [
    [103.6632, 1.32287], [103.66506, 1.30803], [103.67088, 1.32891],
    [103.67636, 1.3354], [103.67669, 1.32779], [103.67927, 1.31477],
    [103.67927, 1.32757], [103.67958, 1.31458], [103.68508, 1.32469],
    [103.6927, 1.3386], [103.69367, 1.34], [103.69377, 1.37058],
    [103.69431, 1.37161], [103.69519, 1.35543], [103.69538, 1.34725],
    [103.6961, 1.33667], [103.696918716667, 1.35110788333333],
    [103.69731, 1.35], [103.698615333333, 1.33590666666667],
    [103.69975, 1.35], [103.70129, 1.34], [103.70247, 1.34],
    [103.70366, 1.34], [103.70394, 1.33948], [103.70403, 1.34081],
    [103.704697166667, 1.33546383333333], [103.70504, 1.34],
    [103.706281333333, 1.344646], [103.70689, 1.34464]
];

const k = 3;
const closestPointsResult = closestPoints(data, pointOfInterest, k);
console.log(closestPointsResult);
```

This implementation uses a priority queue to keep track of the closest points efficiently. It adds each point to the priority queue and pops the smallest one until it has collected the `k` closest points.

This approach ensures that you get the `k` closest points with minimal computational effort.

Questions:
Title: Sorting words from argv by length.
Body: <p>I'm attempting to read words from the command line using <code>argv</code> in C and then sort them in descending order based on their lengths. However, my sorting algorithm is producing unexpected output.</p>
<p>The code I'm using is as follows:</p>
<pre><code>#include &lt;stdio.h&gt;
#include &lt;string.h&gt;

int main(int argc, char *argv[]) {

    for (int i = 1; i &lt; argc - 1; i++) {
        for (int j = 1; j &lt; argc - i - 1; j++) {
            if (strlen(argv[j]) &lt; strlen(argv[j + 1])) {
                char temp_word[20];
                strcpy(temp_word, argv[j]);
                strcpy(argv[j], argv[j + 1]);
                strcpy(argv[j + 1], temp_word);
            }
        }
    }

    puts(&quot;\n&quot;);
    for (int i = 1; i &lt; argc; i++) {
        printf(&quot;%s &quot;, argv[i]);
    }

    return 0;
}
</code></pre>
<pre><code>gcc test.c -o test
./test I put this words


puwordI wordI I  % 
</code></pre>
<p>Unfortunately, the output is corrupted. I suspect there might be an issue with my sorting logic or how I'm handling the command line arguments. Could someone please review my code and provide guidance on how to correctly sort the words by length?</p>

Answers:
Certainly! The issue lies in the way you're iterating over the command line arguments. The outer loop runs from `i = 1` to `argc - i - 1`, which means it's iterating over the array from the second element to the second-to-last element, but it doesn't account for the fact that the array also contains the program name.

To fix this, you should start the inner loop from `j = 1` and iterate until `j < argc - i - 1`. This will ensure that you're comparing each pair of words correctly.

Here's the corrected code:

```c
#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {

    // Iterate over all pairs of words
    for (int i = 1; i < argc - 1; i++) {
        for (int j = 1; j < argc - i - 1; j++) {
            if (strlen(argv[j]) < strlen(argv[j + 1])) {
                char temp_word[20];
                strcpy(temp_word, argv[j]);
                strcpy(argv[j], argv[j + 1]);
                strcpy(argv[j + 1], temp_word);
            }
        }
    }

    puts("\n");
    for (int i = 1; i < argc; i++) {
        printf("%s ", argv[i]);
    }

    return 0;
}
```

With this correction, the output should be correct:

```
I put this words
```

Let me know if you have any further questions or need additional assistance!

Questions:
Title: Interview Question &quot;An Optimized Solution for the given Problem&quot;.
Body: <p>Recently I was going through an interview and interviewer asked me very interesting question.</p>
<p>we are  given a integer matrix for &quot;N x M&quot; we can jump to any number which is strictly greater than  current number in the same row or column. we need to find what is the maximum number of cells we can visit. we can start from any point within the matrix.</p>
<p>Example :-</p>
<pre><code> {1, 0, 10}, 
 {3, 9, 7}, 
 {2, 6, 5}
</code></pre>
<p>Answer :- 6</p>
<p>Explanation :- In this case we have multiple correct paths one of the path is given below.</p>
<p>0 =&gt; 1 =&gt; 2 =&gt; 3 =&gt; 7 =&gt; 10</p>
<p>I write my solution for the given problem in Java</p>
<p>Time Complexity :-  N * M * (N + M)</p>
<p>Space Complexity :- N * M</p>
<p><a href="https://i.stack.imgur.com/c2bF1.png" rel="nofollow noreferrer">enter image description here</a></p>
<pre><code>static void longestIncreasingPath(int[][] matrix) {
    int n = matrix.length;
    int m = matrix[0].length;

    int[][] dp = new int[n][m];
    for (int i = 0; i &lt; n; i++)
        Arrays.fill(dp[i], -1);

    int answer = 0;
    for (int i = 0; i &lt; n; i++) {
        for (int j = 0; j &lt; m; j++) {
            int length = findSolution(i, j, n, m, matrix, dp);
            answer = Math.max(answer, length);
        }
    }

    System.out.println(&quot;Longest increasing path length: &quot; + answer);
}

static int findSolution(int i, int j, int n, int m, int[][] matrix, int[][] dp) {
    if (dp[i][j] != -1) return dp[i][j];

    int res = 1;
    int cur = matrix[i][j];

    for (int newI = 0; newI &lt; n; newI++) {
        int newValue = matrix[newI][j];
        if (newValue &gt; cur) {
            int newRes = 1 + findSolution(newI, j, n, m, matrix, dp);
            res = Math.max(res, newRes);
        }
    }

    for (int newJ = 0; newJ &lt; m; newJ++) {
        int newValue = matrix[i][newJ];
        if (newValue &gt; cur) {
            int newRes = 1 + findSolution(i, newJ, n, m, matrix, dp);
            res = Math.max(res, newRes);
        }
    }

    return dp[i][j] = res;
}
</code></pre>
<p>and after this interviewer said Solution is Correct and asked me to more optimize it terms of Time-Complexity. That I couldn't able to do.</p>
<p>Can someone help me finding optimized solution for this problem?</p>
<p>When I was searching for optimized solution interviewer gave a hint of &quot;sorting&quot;.</p>
<p>If anyone want to play with my code
<a href="http://tpcg.io/_ERHJNY" rel="nofollow noreferrer">http://tpcg.io/_ERHJNY</a></p>
<p>Few more test cases</p>
<p>[[0, 0, 0], [0, 0, 0], [0, 0, 0]] Output should be 1 in this case. Explanation: 0</p>
<p>[[0, 0, 0], [0, 0, 0], [0, 0, -1]] Output should be 2 in this case. Explanation: -1 =&gt; 0</p>
<p>[[0, 0, 0], [0, 0, 0], [0, 0, 1]] Output should be 2 in this case. Explanation: 0 =&gt; 1</p>

Title: How to efficiently use `std::sort` for an opaque data type with a run-time record length?.
Body: <h2>Question</h2>
<p>I want to use <code>std::sort</code> for an opaque data type with a run-time record length. Here is an <a href="https://stackoverflow.com/a/15047037/1202808">answer</a> to a similar question.</p>
<h2>Attempts</h2>
<p>I have tried indirectly sorting record pointers and indices, but these methods have terrible cache locality because the comparisons need to access randomly distributed rows of the dataset.</p>
<p>I also tried falling back to the <code>C</code> functions <code>qsort</code> which allows for run-time record length. This is better, but it requires a callback function for the comparison. This has two drawbacks, 1) performance suffers compared to using a lambda which can be inlined, and 2) the interface ergonomics are poor because you (probably) have to create a structure to hold a functor for the comparison.</p>
<h2>Possible Idea</h2>
<p>The previously mentioned answer suggested a,</p>
<blockquote>
<p>pod block pseudo reference iterator with a specialized swap,</p>
</blockquote>
<p>but did not give any hints about how that might work.</p>
<h2>Summary</h2>
<p>To summarize, I want a way to call <code>std::sort</code> passing in a lambda for the comparison for an array of opaque data types with run-time record length as the following code demonstrates,</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;iostream&gt;
#include &lt;random&gt;

using std::cout, std::endl;

int main(int argc, const char *argv[]) {
    // We have 100 records each with 50 bytes.
    int nrecords = 100, nbytes = 50;
    std::vector&lt;uint8_t&gt; data(nrecords * nbytes);

    // Generate random data for testing.
    std::uniform_int_distribution&lt;uint8_t&gt; d;
    std::mt19937_64 rng;
    std::generate(data.begin(), data.end(), [&amp;]() { return d(rng); });

    int key_index = 20;
    auto cmp = [&amp;](uint8_t *a, uint8_t *b) {
        int aval = *(int*)(a + key_index), bval = *(int*)(b + key_index);
        return aval &lt; bval;
    };

    // How can I call std::sort with run-time record length?
    // std::sort(data.begin(), ...)
    return 0;
}
</code></pre>
<h2>Iterator Attempt</h2>
<p>I attempted to write an iterator based on the previous suggestion, but I have not been able to get it to compile yet. My <em>iterator-foo</em> is sub-par and I feel like I am making a conceptual error.</p>
<p>Here is the code,</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;algorithm&gt;
#include &lt;random&gt;

struct MemoryIterator {
    using iterator_category = std::forward_iterator_tag;
    using difference_type = std::ptrdiff_t;
    using value_type = uint8_t *;
    using pointer = value_type*;
    using reference = value_type&amp;;

    MemoryIterator(value_type ptr, size_t element_size)
        : ptr_(ptr)
        , element_size_(element_size) {
    }

    reference operator*() {
        return ptr_;
    }

    MemoryIterator&amp; operator++() {
        ptr_ += element_size_;
        return *this;
    }

    MemoryIterator&amp; operator--() {
        ptr_ -= element_size_;
        return *this;
    }

    MemoryIterator operator++(int) {
        auto tmp = *this;
        ++(*this);
        return tmp;
    }

    MemoryIterator operator--(int) {
        auto tmp = *this;
        --(*this);
        return tmp;
    }

    MemoryIterator&amp; operator+=(size_t n) {
        ptr_ += n * element_size_;
        return *this;
    }

    MemoryIterator operator+(size_t n) {
        auto r = *this;
        r += n;
        return r;
    }

    MemoryIterator&amp; operator-=(size_t n) {
        ptr_ -= n * element_size_;
        return *this;
    }

    MemoryIterator operator-(size_t n) {
        auto r = *this;
        r -= n;
        return r;
    }
    friend bool operator==(const MemoryIterator&amp; a, const MemoryIterator&amp; b) {
        return a.ptr_ == b.ptr_;
    }

    friend difference_type operator-(const MemoryIterator&amp; a, const MemoryIterator&amp; b) {
        return a.ptr_ - b.ptr_;
    }

    friend void swap(MemoryIterator a, MemoryIterator b) {
    }

private:
    value_type ptr_;
    size_t element_size_;
};

int main(int argc, const char *argv[]) {
    int nrecords = 100, nbytes = 50;
    std::vector&lt;uint8_t&gt; data(nrecords * nbytes);

    std::uniform_int_distribution&lt;uint8_t&gt; d;
    std::mt19937_64 rng;
    std::generate(data.begin(), data.end(), [&amp;]() { return d(rng); });

    int key_index = 20;
    auto cmp = [&amp;](uint8_t *a, uint8_t *b) {
        int aval = *(int*)(a + key_index), bval = *(int*)(b + key_index);
        return aval &lt; bval;
    };

    MemoryIterator begin(data.data(), nbytes);
    MemoryIterator end(data.data() + data.size(), nbytes); 
    std::sort(begin, end, cmp);

    return 0;
}
</code></pre>
<p>It complains that it cannot compare two <code>MemoryIterator</code>'s which is true -- it needs to use the comparison function.</p>
<h2>Compilation Error</h2>
<pre><code>/opt/local/libexec/llvm-16/bin/../include/c++/v1/__algorithm/sort.h:533:21: error:
      invalid operands to binary expression ('MemoryIterator' and 'MemoryIterator')
            if (__i &gt;= __j)
                ~~~ ^  ~~~
/opt/local/libexec/llvm-16/bin/../include/c++/v1/__algorithm/sort.h:639:8: note:
      in instantiation of function template specialization
      'std::__introsort&lt;std::_ClassicAlgPolicy, (lambda at
      sort0.cpp:92:16) &amp;, MemoryIterator&gt;' requested here
  std::__introsort&lt;_AlgPolicy, _Compare&gt;(__first, __last, __comp, __depth_limit);
       ^
/opt/local/libexec/llvm-16/bin/../include/c++/v1/__algorithm/sort.h:699:10: note:
      in instantiation of function template specialization 'std::__sort&lt;(lambda at
      sort0.cpp:92:16) &amp;, MemoryIterator&gt;' requested here
    std::__sort&lt;_WrappedComp&gt;(std::__unwrap_iter(__first), std::__unwrap_iter(__last), _...
</code></pre>

Title: Using std::thread to call std::sort directly.
Body: <p>How can I make a thread execute <code>std::sort()</code> directly, without creating an intermediate function?</p>
<p>Something like:</p>
<pre class="lang-cpp prettyprint-override"><code>std::thread t1(std::sort, data.begin(), data.end());
</code></pre>
<p>My (playground!) idea is letting each thread sort half of the vector and then merge it:</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;vector&gt;
#include &lt;thread&gt;
#include &lt;iostream&gt;
#include &lt;algorithm&gt;

// Type your code here, or load an example.
void myfunc(std::vector&lt;int&gt;&amp; data) {
    std::sort(data.begin(), data.begin() + data.size() / 2);
    return;
}

int main()
{    
    std::vector&lt;int&gt; data = { 1, 8, 123, 10, -3, 15, 2, 7 };
    std::thread t1(myfunc, std::ref(data)); // works
    //std::thread t1(std::sort, data.begin(), data.begin() + data.size() / 2); // doesn't
    std::sort(data.begin() + data.size() / 2, data.end());
    t1.join();
    std::inplace_merge(data.begin(), data.begin() + data.size() / 2, data.end());

    for (auto x : data)
        std::cout &lt;&lt; x &lt;&lt; &quot;\n&quot;;
}
</code></pre>
<p>Compiler error, when using the commented line instead of the one above (I used an online code editor):</p>
<pre class="lang-none prettyprint-override"><code>error: no matching function for call to 'std::thread::thread(&lt;unresolved overloaded function type&gt;, std::vector&lt;int&gt;::iterator, __gnu_cxx::__normal_iterator&lt;int*, std::vector&lt;int&gt; &gt;)'
   16 | d t1(std::sort, data.begin(), data.begin() + data.size() / 2); // doesn't
      |                                                             ^

In file included from /usr/include/c++/11/thread:43,
                 from /tmp/bBJEjs0nrj.cpp:2:
/usr/include/c++/11/bits/std_thread.h:127:7: note: candidate: 'template&lt;class _Callable, class ... _Args, class&gt; std::thread::thread(_Callable&amp;&amp;, _Args&amp;&amp; ...)'
  127 |       thread(_Callable&amp;&amp; __f, _Args&amp;&amp;... __args)
      |       ^~~~~~
/usr/include/c++/11/bits/std_thread.h:127:7: note:   template argument deduction/substitution failed:
/tmp/bBJEjs0nrj.cpp:16:75: note:   couldn't deduce template parameter '_Callable'
   16 | d t1(std::sort, data.begin(), data.begin() + data.size() / 2); // doesn't
      |                                                             ^

In file included from /usr/include/c++/11/thread:43,
                 from /tmp/bBJEjs0nrj.cpp:2:
/usr/include/c++/11/bits/std_thread.h:157:5: note: candidate: 'std::thread::thread(std::thread&amp;&amp;)'
  157 |     thread(thread&amp;&amp; __t) noexcept
      |     ^~~~~~
/usr/include/c++/11/bits/std_thread.h:157:5: note:   candidate expects 1 argument, 3 provided
/usr/include/c++/11/bits/std_thread.h:121:5: note: candidate: 'std::thread::thread()'
  121 |     thread() noexcept = default;
      |     ^~~~~~
/usr/include/c++/11/bits/std_thread.h:121:5: note:   candidate expects 0 arguments, 3 provided
</code></pre>
<p>Desired output:</p>
<pre class="lang-none prettyprint-override"><code>-3,1,27,8,10,15,123
</code></pre>

Title: How can zod date type accept ISO date strings?.
Body: <p>When defining a schema with zod, how do I use a date type?</p>
<p>If I use <code>z.date()</code> (see below) the date object is serialized to a ISO date string. But then if I try to parse it back with zod, the validator fails because a string is not a date.</p>
<pre><code>import { z } from &quot;zod&quot;

const someTypeSchema = z.object({
    t: z.date(),
})
type SomeType = z.infer&lt;typeof someTypeSchema&gt;

function main() {
    const obj1: SomeType = {
        t: new Date(),
    }
    const stringified = JSON.stringify(obj1)
    console.log(stringified)
    const parsed = JSON.parse(stringified)
    const validated = someTypeSchema.parse(parsed) // &lt;- Throws error! &quot;Expected date, received string&quot;
    console.log(validated.t)
}
main()
</code></pre>

Answers:
You can use zod's <code>z.coerce.date()</code> to accept ISO date strings and parse them into Date objects. Here's an example:
<pre><code>import { z } from "zod";

const someTypeSchema = z.object({
    t: z.coerce.date(),
});

type SomeType = z.infer<typeof someTypeSchema>;

function main() {
    const obj1: SomeType = {
        t: new Date(),
    };
    const stringified = JSON.stringify(obj1);
    console.log(stringified);
    const parsed = JSON.parse(stringified);
    const validated = someTypeSchema.parse(parsed);
    console.log(validated.t);
}
main();
</code></pre>
This will parse the ISO date string into a Date object when validating the schema.

Questions:
Title: How to trigger SwiftUI DatePicker Programmatically?.
Body: <p>As Image below shows, if you type the date &quot;Jan 11 2023&quot;, it presents the date picker. What I wanna to achieve is have a button elsewhere, when that button is clicked, present this date picker automatically.</p>
<p>Does anyone know if there is a way to achieve it?</p>
<pre><code>DatePicker(&quot;Jump to&quot;, selection: $date, in: dateRange, displayedComponents: [.date]) 
</code></pre>
<p><a href="https://i.stack.imgur.com/pGgkZ.jpg" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/pGgkZ.jpg" alt="enter image description here" /></a></p>
<p>Below is a test on @rob mayoff's answer. I still couldn't
figure out why it didn't work yet.</p>
<p>I tested on Xcode 14.2 with iPhone 14 with iOS 16.2 simulator, as well as on device. What I noticed is that although the <code>triggerDatePickerPopover()</code> is called, it never be able to reach <code>button.accessibilityActivate()</code>.</p>
<pre><code>import SwiftUI

struct ContentView: View {
  @State var date: Date = .now
  let dateRange: ClosedRange&lt;Date&gt; = Date(timeIntervalSinceNow: -864000) ... Date(timeIntervalSinceNow: 864000)

  var pickerId: String { &quot;picker&quot; }

  var body: some View {
    VStack {
      DatePicker(
        &quot;Jump to&quot;,
        selection: $date,
        in: dateRange,
        displayedComponents: [.date]
      )
      .accessibilityIdentifier(pickerId)

      Button(&quot;Clicky&quot;) {
        triggerDatePickerPopover()
          print(&quot;Clicky Triggered&quot;)
      }
    }
    .padding()
  }
}

struct ContentView_Previews: PreviewProvider {
    static var previews: some View {
        ContentView()
    }
}

extension NSObject {
  func accessibilityDescendant(passing test: (Any) -&gt; Bool) -&gt; Any? {

    if test(self) { return self }

    for child in accessibilityElements ?? [] {
      if test(child) { return child }
      if let child = child as? NSObject, let answer = child.accessibilityDescendant(passing: test) {
        return answer
      }
    }

    for subview in (self as? UIView)?.subviews ?? [] {
      if test(subview) { return subview }
      if let answer = subview.accessibilityDescendant(passing: test) {
        return answer
      }
    }

    return nil
  }
}


extension NSObject {
  func accessibilityDescendant(identifiedAs id: String) -&gt; Any? {
    return accessibilityDescendant {
      // For reasons unknown, I cannot cast a UIView to a UIAccessibilityIdentification at runtime.
      return ($0 as? UIView)?.accessibilityIdentifier == id
      || ($0 as? UIAccessibilityIdentification)?.accessibilityIdentifier == id
    }
  }

    func buttonAccessibilityDescendant() -&gt; Any? {
       return accessibilityDescendant { ($0 as? NSObject)?.accessibilityTraits == .button }
     }
}

extension ContentView {
  func triggerDatePickerPopover() {
    if
      let scene = UIApplication.shared.connectedScenes.first as? UIWindowScene,
      let window = scene.windows.first,
      let picker = window.accessibilityDescendant(identifiedAs: pickerId) as? NSObject,
      let button = picker.buttonAccessibilityDescendant() as? NSObject
    {
        print(&quot;triggerDatePickerPopover&quot;)
      button.accessibilityActivate()
    }
  }
}
</code></pre>
<p><a href="https://i.stack.imgur.com/eVDwL.gif" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/eVDwL.gif" alt="enter image description here" /></a></p>
<p>Update 2:
I followed up the debug instruction. It seems that with exact same code. My inspector are missing the accessibility identifier. Not knowing why.... feels mind buggingly now.
<a href="https://i.stack.imgur.com/gnAa8.jpg" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/gnAa8.jpg" alt="enter image description here" /></a></p>
<p>Here is a link to download the project <a href="https://www.icloud.com/iclouddrive/040jHC0jwwJg3xgAEvGZShqFg#DatePickerTest" rel="nofollow noreferrer">https://www.icloud.com/iclouddrive/040jHC0jwwJg3xgAEvGZShqFg#DatePickerTest</a></p>
<p>Update 3:
@rob mayoff's solution is brilliant! For anyone reading. If it didn't work in your case, just wait. It's probably just due to device or simulator getting ready for accessibility.</p>

Answers:
To utilize `d3.extent()` in TypeScript, you need to ensure that the dates are properly typed. Here's a step-by-step solution:

1. **Ensure Dates Are Properly Typed:**

   First, make sure that your dates are typed as `Date` objects. You can achieve this by creating a custom type or using a utility type.

   ```typescript
   import * as d3 from 'd3';

   // Define a custom type for dates
   type DateValue = Date | null;

   const dates: DateValue[] = data.map((row) => {
     const date = d3.timeParse('%Y-%m-%d')(row.Date);
     return date;
   });

   // Filter out null values
   const validDates = dates.filter((date) => date !== null) as Date[];

   // Now use d3.extent
   const extent = d3.extent(validDates);

   // Ensure the extent is of type [Date, Date]
   console.log(extent); // Output will be [Date, Date]
   ```

2. **Check the Type of `d3.extent`:**

   The `d3.extent` function returns a tuple of type `[Date, Date]`. Ensure that your `validDates` array is correctly typed.

3. **Use `d3.extent` Correctly:**

   When calling `d3.extent`, make sure the input is of the correct type.

   ```typescript
   const xScale = d3.scaleTime().domain(d3.extent(validDates));
   ```

4. **Ensure Data is Correct:**

   Verify that your `data` array is correctly formatted and contains valid dates.

   ```typescript
   const data = [
     { Date: '2023-06-24' },
     { Date: '2023-06-24' },
     { Date: '2023-06-23' },
     { Date: '2023-06-23' },
     { Date: '2023-06-23' },
     // ...
   ];
   ```

5. **Filter Out `null` Values:**

   Filter out `null` values from your `dates` array to ensure that only valid `Date` objects are included.

   ```typescript
   const validDates = dates.filter((date) => date !== null) as Date[];
   ```

6. **Check the Type of `validDates`:**

   Ensure that `validDates` is of type `Date[]`.

   ```typescript
   console.log(typeof validDates[0]); // Output will be 'object'
   ```

By following these steps, you should be able to correctly use `d3.extent` with your dates in TypeScript.

Questions:
Title: How to check if date picker is opened or closed in view SwiftUI. without Tap Gesture on Date picker.
Body: <p>When the user hits date picker in swiftUI, it opens up and shows calendar to choose date user may or may not choose date and user hits somewhere else in the view and date picker closes it self. I want to change date picker parent view border when user hits date picker and also when user tap somewhere else screen date picker closes and its parent view border does not changes.I want to handle the date picker parent view border color. when then date picker is closed or dismissed.<a href="https://i.stack.imgur.com/vX0Bv.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/vX0Bv.png" alt="this date picker in parent view" /></a> <a href="https://i.stack.imgur.com/e3nF1.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/e3nF1.png" alt="changing date picker parent view border color on tap gesture" /></a><a href="https://i.stack.imgur.com/om89W.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/om89W.png" alt="date picker dismissed/closed but unable to detect when date picker is closed. " /></a></p>
<pre><code>DatePicker(&quot;&quot;, selection: $datePicker, displayedComponents: .date)
                    .labelsHidden()
                    .padding(.trailing, 8)
                    .frame(alignment: .leading)
                    .colorMultiply(AppColors.textNavy100Color)
                    .accentColor(AppColors.textNavy100Color)
                    .onTapGesture {
                        print(&quot;date picker tapped&quot;)
                        if isFieldEditing == false{
                            isFieldEditing = true
                        }else {
                           isFieldEditing = false
                        }
                    }
</code></pre>

Answers:
To check if the date picker is opened or closed in SwiftUI without tapping on it, you can use the `onReceive` modifier to observe changes in the `datePicker` variable. You can also use the `isFieldEditing` variable to keep track of the state of the date picker.

Here's an example of how you can implement this:

```swift
@State private var datePicker: Date = Date()
@State private var isFieldEditing = false

var body: some View {
    DatePicker("", selection: $datePicker, displayedComponents: .date)
        .labelsHidden()
        .padding(.trailing, 8)
        .frame(alignment: .leading)
        .colorMultiply(AppColors.textNavy100Color)
        .accentColor(AppColors.textNavy100Color)
        .onReceive($datePicker) { newValue in
            if isFieldEditing == false {
                isFieldEditing = true
            } else {
                isFieldEditing = false
            }
        }
}
```

In this example, the `onReceive` modifier observes changes in the `datePicker` variable. When the `datePicker` value changes, the closure is executed, and the `isFieldEditing` variable is toggled.

You can then use the `isFieldEditing` variable to control the appearance of the date picker and the parent view border. For example, you can change the parent view border color when `isFieldEditing` is `true` and revert it to its original color when `isFieldEditing` is `false`.

```swift
var body: some View {
    DatePicker("", selection: $datePicker, displayedComponents: .date)
        .labelsHidden()
        .padding(.trailing, 8)
        .frame(alignment: .leading)
        .colorMultiply(isFieldEditing ? AppColors.textNavy100Color : AppColors.defaultBorderColor)
        .accentColor(isFieldEditing ? AppColors.textNavy100Color : AppColors.defaultAccentColor)
        .onReceive($datePicker) { newValue in
            if isFieldEditing == false {
                isFieldEditing = true
            } else {
                isFieldEditing = false
            }
        }
}
```

In this example, the parent view border color is set to `AppColors.textNavy100Color` when `isFieldEditing` is `true`, and to `AppColors.defaultBorderColor` when `isFieldEditing` is `false`. Similarly, the accent color is set to `AppColors.textNavy100Color` when `isFieldEditing` is `true`, and to `AppColors.defaultAccentColor` when `isFieldEditing` is `false`.

This way, you can detect when the date picker is opened or closed without tapping on it, and control the appearance of the parent view border accordingly.

You can also use the `isFieldEditing` variable to detect when the date picker is dismissed or closed. For example, you can use the `onDismiss` modifier to execute a closure when the date picker is dismissed:

```swift
DatePicker("", selection: $datePicker, displayedComponents: .date)
    .labelsHidden()
    .padding(.trailing, 8)
    .frame(alignment: .leading)
    .colorMultiply(isFieldEditing ? AppColors.textNavy100Color : AppColors.defaultBorderColor)
    .accentColor(isFieldEditing ? AppColors.textNavy100Color : AppColors.defaultAccentColor)
    .onReceive($datePicker) { newValue in
        if isFieldEditing == false {
            isFieldEditing = true
        } else {
            isFieldEditing = false
        }
    }
    .onDismiss {
        print("Date picker dismissed")
        isFieldEditing = false
    }
```

In this example, the `onDismiss` modifier executes a closure when the date picker is dismissed. The `isFieldEditing` variable is set to `false` to revert the appearance of the parent view border.

This way, you can detect when the date picker is dismissed or closed without tapping on it, and control the appearance of the parent view border accordingly.<|fim_middle|>

