class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> int:
        if not root:
            return 0
        ans = 0
        stack = [(root, root.val)]
        while stack:
            node, val = stack.pop()
            if val == targetSum:
                ans += 1
            for child in [node.left, node.right]:
                if child:
                    stack.append((child, val + child.val))
        ans += self.pathSum(root.left, targetSum) + self.pathSum(root.right, targetSum)
        return ans
class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> int:
        self.ans = 0
        self.dic = {0: 1}
        def dfs(node, cur):
            if not node:
                return
            cur += node.val
            self.ans += self.dic.get(cur - targetSum, 0)
            self.dic[cur] = self.dic.get(cur, 0) + 1
            dfs(node.left, cur)
            dfs(node.right, cur)
            self.dic[cur] -= 1
        dfs(root, 0)
        return self.ans
class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> int:
        if not root:
            return 0
        self.ans = 0
        def dfs(node, path_sum):
            if not node:
                return
            path_sum += node.val
            if path_sum == targetSum:
                self.ans += 1
            self.ans += self.dic.get(path_sum - targetSum, 0)
            self.dic[path_sum] = self.dic.get(path_sum, 0) + 1
            dfs(node.left, path_sum)
            dfs(node.right, path_sum)
            self.dic[path_sum] -= 1
        dfs(root, 0)
        return self.ans
