from typing import Dict, Optional, Union

from fastapi import APIRouter, Depends, Request, Response
from fastapi.responses import RedirectResponse

from .utils import get_current_user

router = APIRouter()


@router.get("/redirect")
async def redirect(
    request: Request,
    response: Response,
    user: Optional[Dict] = Depends(get_current_user),
    redirect_url: Optional[str] = None,
    **kwargs,
):
    if redirect_url:
        return RedirectResponse(redirect_url, status_code=302)
    return RedirectResponse(request.url_for("index"), status_code=302)


@router.get("/redirect/{path}")
async def redirect_path(
    request: Request,
    response: Response,
    user: Optional[Dict] = Depends(get_current_user),
    path: Optional[str] = None,
    **kwargs,
):
    if path:
        return RedirectResponse(request.url_for(path), status_code=302)
    return RedirectResponse(request.url_for("index"), status_code=302)


@router.get("/redirect/{path}/{path_2}")
async def redirect_path_2(
    request: Request,
    response: Response,
    user: Optional[Dict] = Depends(get_current_user),
    path: Optional[str] = None,
    path_2: Optional[str] = None,
    **kwargs,
):
    if path and path_2:
        return RedirectResponse(request.url_for(f"{path}/{path_2}"), status_code=302)
    return RedirectResponse(request.url_for("index"), status_code=302)


@router.get("/redirect/{path}/{path_2}/{path_3}")
async def redirect_path_3(
    request: Request,
    response: Response,
    user: Optional[Dict] = Depends(get_current_user),
    path: Optional[str] = None,
