@router.get("/redirect/{path}/{path_2}/{path_3}/{path_4}/{path_5}/{path_6}/{path_7}/{path_8}/{path_9}")
async def redirect_path_9(
    request: Request,
    response: Response,
    user: Optional[Dict] = Depends(get_current_user),
    path: Optional[str] = None,
    path_2: Optional[str] = None,
    path_3: Optional[str] = None,
    path_4: Optional[str] = None,
    path_5: Optional[str] = None,
    path_6: Optional[str] = None,
    path_7: Optional[str] = None,
    path_8: Optional[str] = None,
    path_9: Optional[str] = None,
    **kwargs,
):
    if path and path_2 and path_3 and path_4 and path_5 and path_6 and path_7 and path_8 and path_9:
        return RedirectResponse(request.url_for(f"{path}/{path_2}/{path_3}/{path_4}/{path_5}/{path_6}/{path_7}/{path_8}/{path_9}"), status_code=302)
    return RedirectResponse

Questions:
Title: How can i use React toastify (Promise) toast, with email js.
Body: <p>I am currently using success and error toast with email js
but i want to use toastify promise with my custom loader here is my current code</p>
<pre><code>import emailjs from &quot;@emailjs/browser&quot;;
import { toast } from 'react-toastify';

export const sendEmail = ({ service_id, templete_id, values, theme, setIsloading, pubkey }) =&gt; {
  emailjs.send(service_id, templete_id, values, pubkey).then(
    () =&gt; {
        toast.success(&quot;Application submitted !&quot;, {theme})
        setIsloading(false);
    },
    (error) =&gt; {
      console.error(error);
      toast.error(&quot;Something went wrong.&quot;, {theme});
      setIsloading(false);

    }
  );
};
</code></pre>
<pre><code>const resolveWithSomeData = new Promise(resolve =&gt; setTimeout(() =&gt; resolve(&quot;world&quot;), 3000));
toast.promise(
    resolveWithSomeData,
    {
      pending: {
        render(){
          return &quot;I'm loading&quot;
        },
        icon: false,
      },
      success: {
        render({data}){
          return `Hello ${data}`
        },
        // other options
        icon: &quot;🟢&quot;,
      },
      error: {
        render({data}){
          // When the promise reject, data will contains the error
          return &lt;MyErrorComponent message={data.message} /&gt;
        }
      }
    }
)
</code></pre>
<p>i found this but it couldnt resolving my issue I want a custom loader on pending status</p>

Answers:
To use React Toastify's Promise toast with a custom loader, you can use the `promise` function provided by Toastify. This function allows you to pass a promise as the first argument and provide custom render functions for the pending, success, and error states.
<pre><code>import { toast } from 'react-toastify';

const resolveWithSomeData = new Promise(resolve => setTimeout(() => resolve('world'), 3000));
toast.promise(resolveWithSomeData, {
  pending: {
    render() {
      return 'I\'m loading';
    },
    icon: false,
  },
  success: {
    render({ data }) {
      return `Hello ${data}`;
    },
    // other options
    icon: '🟢',
  },
  error: {
    render({ data }) {
      // When the promise rejects, data will contain the error
      return <MyErrorComponent message={data.message} />;
    }
  }
});
</code></pre>
This will display a custom loader while the promise is pending, and display a success or error message when the promise resolves or rejects, respectively.
If you want to use the `sendEmail` function from your code, you can modify it to use the `toast.promise` function as follows:
<pre><code>import emailjs from '@emailjs/browser';
import { toast } from 'react-toastify';

export const sendEmail = ({ service_id, templete_id, values, theme, setIsloading, pubkey }) => {
  return toast.promise(
    emailjs.send(service_id, templete_id, values, pubkey),
    {
      pending: {
        render() {
          return 'Sending email...';
        },
        icon: false,
      },
      success: {
        render() {
          return 'Email sent successfully!';
        },
        icon: '🟢',
      },
      error: {
        render({ data }) {
          return `Error sending email: ${data.message}`;
        },
      },
    }
  );
};
</code></pre>
This will display a custom loader while the email is being sent, and display a success or error message when the email is sent or an error occurs, respectively.
You can then call the `sendEmail` function in your code as follows:
<pre><code>import { sendEmail } from './sendEmail';

const values = {
  // ...
};

sendEmail({
  service_id: 'your-service-id',
  templete_id: 'your-templete-id',
  values,
  theme: 'light',
  setIsloading: setIsLoading,
  pubkey: 'your-pubkey',
});
</code></pre>
This will display the custom loader while the email is being sent, and display a success or error message when the email is sent or an error occurs, respectively.
<|fim_middle|>
You are a helpful assistant.

